:"code_node_FLgate","type":"code-node","properties":{"language":"javascript","code":"","timeout":30000,"isValidator":true,"nodeName":"IA floor: switch and gate","name":"IA floor: switch and gate","script":{"type":"javascript","code":"// MIN-01 RF-03: a Reserved subtract may not take the bucket below the open Item Assembly holds on this row. The IA's own
// completion (transaction type IA) is exempt: it takes Reserved only up to its own holds.
const IA_FLOOR_ENABLED = false;
const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const D = /^[0-9]{1,20}$/;
const cat = s([{{workflowparams:inventory_category}}][0]);
const tt = s([{{workflowparams:transaction_type}}][0]);
const trx = s([{{workflowparams:trx_no}}][0]);
